$('#recipeBookBtn').onclick=()=>{$('#recipeList').classList.toggle('hidden')};function buildRecipeBook(){const list=$('#recipeList');list.innerHTML='';for(const r of RECIPES){const e=document.createElement('div');e.className='recipe-entry';const ic=document.createElement('i');ic.className='slot-icon';ic.style.backgroundImage=`url(${atlasURL})`;ic.style.backgroundPosition=tilePos(itemDef(r.out).tile);const t=document.createElement('span');t.textContent=itemDef(r.out).name+' ×'+r.count+' · '+(r.station==='table'?'Table':'Hand');e.append(ic,t);e.onclick=()=>toast('Arrange the shown ingredients in the crafting grid');list.appendChild(e)}}
