// ---------- World library and saves ----------
const furnaces=new Map(),chests=new Map();
function worldMetaList(){try{return JSON.parse(STORE.getItem('br3_worlds')||'[]')}catch{return[]}}
function saveWorldMeta(list){STORE.setItem('br3_worlds',JSON.stringify(list))}
function worldSaveKey(id){return'br3_save_'+id}
function renderWorldList(){const list=worldMetaList(),root=$('#worldList');root.innerHTML='';if(!list.length){root.innerHTML='<div class="empty-worlds"><h3>NO WORLDS YET</h3><p>Create a procedural realm and start surviving.</p></div>';return}list.sort((a,b)=>(b.lastPlayed||0)-(a.lastPlayed||0));for(const w of list){const card=document.createElement('article');card.className='world-card';card.innerHTML=`<div class="world-thumb"></div><div class="world-info"><h3></h3><p class="seed"></p><p class="meta"></p></div><div class="world-actions"><button class="mc-btn tiny play">PLAY</button><button class="mc-btn tiny danger del">DELETE</button></div>`;card.querySelector('h3').textContent=w.name;card.querySelector('.seed').textContent='Seed: '+w.seed;card.querySelector('.meta').textContent=`${w.mode.toUpperCase()} · Day ${w.dayCount||1} · ${new Date(w.lastPlayed||w.created).toLocaleDateString()}`;card.querySelector('.play').onclick=()=>startWorld(w.id);card.querySelector('.del').onclick=()=>{if(confirm('Delete “'+w.name+'” permanently?')){STORE.removeItem(worldSaveKey(w.id));saveWorldMeta(worldMetaList().filter(x=>x.id!==w.id));renderWorldList()}};root.appendChild(card)}}
function randomSeed(){return Math.random().toString(36).slice(2,10).toUpperCase()+'-'+Date.now().toString(36).slice(-4).toUpperCase()}
function createWorld(){const name=$('#worldName').value.trim()||'New Realm',seedText=$('#worldSeed').value.trim()||randomSeed(),id='w_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),meta={id,name,seed:seedText,mode:$('#worldMode').value,difficulty:$('#worldDifficulty').value,created:Date.now(),lastPlayed:Date.now(),dayCount:1,bonusChest:$('#bonusChest').checked,startingMap:$('#startingMap').checked};const list=worldMetaList();list.push(meta);saveWorldMeta(list);closeScreen(dom.create);startWorld(id)}
$('#createWorldConfirm').onclick=createWorld;$('#newWorldBtn').onclick=()=>{closeScreen(dom.main);openScreen(dom.create);$('#worldSeed').value=''};$('#createFromList').onclick=()=>{closeScreen(dom.worlds);openScreen(dom.create)};$('#playMenuBtn').onclick=()=>{renderWorldList();closeScreen(dom.main);openScreen(dom.worlds)};$('#aboutBtn').onclick=()=>openScreen(dom.about);
function saveFurnace(){if(!furnaceState.pos)return;const k=bkey(...furnaceState.pos);furnaces.set(k,{slots:{input:cloneStack(furnaceSlots.input),fuel:cloneStack(furnaceSlots.fuel),output:cloneStack(furnaceSlots.output)},burn:furnaceState.burn,burnMax:furnaceState.burnMax,cook:furnaceState.cook,cookMax:furnaceState.cookMax})}
function loadFurnace(pos){const f=furnaces.get(bkey(...pos));furnaceSlots.input=cloneStack(f?.slots.input);furnaceSlots.fuel=cloneStack(f?.slots.fuel);furnaceSlots.output=cloneStack(f?.slots.output);furnaceState.burn=f?.burn||0;furnaceState.burnMax=f?.burnMax||0;furnaceState.cook=f?.cook||0;furnaceState.cookMax=f?.cookMax||8}
function serializeMap(m){return[...m.entries()]}
