 const speed=Math.hypot(player.vx,player.vz);player.stepClock+=speed*dt;if(player.onGround&&speed>.8&&player.stepClock>2.3){player.stepClock=0;audio.play('step')}survivalClock+=dt;if(survivalClock>=1){survivalClock-=1;if(game.mode!=='creative'){if(player.sprinting&&speed>2)player.hunger=Math.max(0,player.hunger-.03);else player.hunger=Math.max(0,player.hunger-.005);if(player.saturation>0&&player.hunger<20){player.saturation=Math.max(0,player.saturation-.01);player.hunger=Math.min(20,player.hunger+.004)}if(player.oxygen<=0){starveClock++;if(starveClock>=2){starveClock=0;damagePlayer(1,'Drowning')}}else if(player.hunger<=0){starveClock++;if(starveClock>=4){starveClock=0;damagePlayer(game.difficulty==='hard'?2:1,'Starvation')}}else starveClock=0;if(player.hunger>=18&&player.health<20){regenClock++;if(regenClock>=5){regenClock=0;player.health=Math.min(20,player.health+1);player.hunger=Math.max(0,player.hunger-.2)}}else regenClock=0}updateVitals()}
