function spawnDrop(id,count,x,y,z){if(!count)return;drops.push({id,count,x,y,z,vx:(Math.random()-.5)*1.5,vy:2.6,vz:(Math.random()-.5)*1.5,age:0,spin:Math.random()*6.28})}
