function updateVitals(){const make=(root,count,max,cls)=>{root.innerHTML='';for(let i=0;i<max;i++){const e=document.createElement('i');e.className='status-icon '+cls;if(count<=i)e.classList.add('empty');else if(count<i+1)e.classList.add('half');root.appendChild(e)}};make($('#healthBar'),player.health/2,10,'heart');make($('#hungerBar'),player.hunger/2,10,'food');const ar=$('#armorBar');ar.innerHTML='';for(let i=0;i<10;i++){const e=document.createElement('i');e.className='armor-pip'+(player.armor/2<=i?' empty':'');ar.appendChild(e)}const ox=$('#oxygenBar');ox.innerHTML='';if(player.oxygen<10){for(let i=0;i<10;i++){const e=document.createElement('i');e.className='bubble'+(player.oxygen<=i?' empty':'');ox.appendChild(e)}}$('#xpFill').style.width=clamp(player.xp/(7+player.level*3)*100,0,100)+'%';$('#xpLevel').textContent=player.level}
function skyState(){const a=game.day*Math.PI*2-Math.PI/2,elev=Math.sin(a),az=Math.cos(a),sun=clamp((elev+.16)/.76,0,1),twilight=clamp(1-Math.abs(elev)*3.4,0,1),l=Math.hypot(az*.78,elev,.54)||1,dir=[az*.78/l,elev/l,.54/l],moonDir=[-dir[0],-dir[1],-dir[2]];const cinematic=effectiveShaderProfile()==='cinematic'?1:0;return{sun,r:lerp(.018,.47,sun)+twilight*(.12+.04*cinematic),g:lerp(.032,.70,sun)+twilight*.045,b:lerp(.075,.91,sun),angle:a,dir,moonDir,twilight}}
