let celestialCache={at:0,sun:1,moon:1};
function celestialExposure(dir){if(dir[1]<-.08)return 0;const e=eyePos();let leafHits=0,last='';for(let t=.45;t<72;t+=.48){const x=Math.floor(e[0]+dir[0]*t),y=Math.floor(e[1]+dir[1]*t),z=Math.floor(e[2]+dir[2]*t),k=bkey(x,y,z);if(k===last)continue;last=k;const b=getBlock(x,y,z);if(!b||b===B.WATER||b===B.GLASS)continue;if(b===B.OAK_LEAVES||b===B.SPRUCE_LEAVES){leafHits++;if(leafHits<3)continue;return .18}if(BLOCKS[b]?.solid)return 0}return leafHits?Math.max(.35,1-leafHits*.2):1}
