function torchSource(){const s=selectedStack();if(s?.id===B.TORCH)return[player.x,player.y+player.eye-.15,player.z,1];let best=81,out=[0,0,0,0];for(const[k,v]of mods)if(v===B.TORCH){const[x,y,z]=k.split(',').map(Number),d=(x+.5-player.x)**2+(y+.5-(player.y+player.eye))**2+(z+.5-player.z)**2;if(d<best){best=d;out=[x+.5,y+.65,z+.5,1]}}return out}
function renderFrame(){if(!rendererReady)return;resizeRenderer();const sky=skyState(),e=eyePos(),d=lookDir();M4.perspective(proj,settings.fov*Math.PI/180,dom.canvas.width/dom.canvas.height,.05,(settings.viewDistance+1.7)*CH);M4.look(view,e,[e[0]+d[0],e[1]+d[1],e[2]+d[2]],[0,1,0]);M4.mul(vp,proj,view);updateSkyDOM(sky);gl.clearColor(sky.r,sky.g,sky.b,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);gl.enable(gl.CULL_FACE);gl.disable(gl.BLEND);const torch=torchSource();for(const m of chunkMeshes.values())drawWorldMesh(m.opaque,programOpaque,sky,torch,false);for(const m of mobs)if(!m.dead)renderMob(m,sky);for(const q of drops)renderDrop(q,sky);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.depthMask(false);for(const m of chunkMeshes.values())drawWorldMesh(m.water,programWater,sky,torch,true);gl.depthMask(true);drawOutline(target);gl.disable(gl.BLEND)}
function updateDay(dt){const old=game.day;game.day=mod(game.day+dt/720,1);if(game.day<old)game.dayCount++;const mins=Math.floor(game.day*24*60),hh=String(Math.floor(mins/60)).padStart(2,'0'),mm=String(mins%60).padStart(2,'0');$('#dayBadge').textContent=`DAY ${game.dayCount} · ${hh}:${mm}`;$('#biomeBadge').textContent=biomeAt(Math.floor(player.x),Math.floor(player.z)).toUpperCase()}
function processMeshQueue(limit=1){let n=0;while(meshQueue.length&&n<limit){const k=meshQueue.shift();if(!desiredChunks.has(k))continue;const[cx,cz]=k.split(',').map(Number);meshChunk(cx,cz);n++}}
