function streamChunks(force=false){const pcx=Math.floor(player.x/CH),pcz=Math.floor(player.z/CH);if(!force&&!game.forceRestream&&pcx===lastChunkX&&pcz===lastChunkZ)return;game.forceRestream=false;lastChunkX=pcx;lastChunkZ=pcz;const next=new Set(),arr=[];for(let dz=-settings.viewDistance;dz<=settings.viewDistance;dz++)for(let dx=-settings.viewDistance;dx<=settings.viewDistance;dx++){if(dx*dx+dz*dz>(settings.viewDistance+.45)**2)continue;const cx=pcx+dx,cz=pcz+dz,k=ckey(cx,cz);next.add(k);if(!chunkMeshes.has(k))arr.push([k,dx*dx+dz*dz])}arr.sort((a,b)=>a[1]-b[1]);for(const[k]of arr)if(!meshQueue.includes(k))meshQueue.push(k);for(const[k,m]of chunkMeshes)if(!next.has(k)){destroyMesh(m.opaque);destroyMesh(m.water);chunkMeshes.delete(k)}for(const k of chunks.keys()){const[cx,cz]=k.split(',').map(Number);if(Math.abs(cx-pcx)>settings.viewDistance+2||Math.abs(cz-pcz)>settings.viewDistance+2)chunks.delete(k)}desiredChunks=next}
let lowFpsTicks=0,qualityCooldown=0;function adaptiveGraphics(){if(!game.running||!settings.adaptiveQuality||safeMode)return;if(qualityCooldown>0){qualityCooldown--;return}const ep=effectiveShaderProfile(),limit=ep==='cinematic'?24:ep==='reimagined'?18:0;if(limit&&game.fps<limit)lowFpsTicks++;else lowFpsTicks=Math.max(0,lowFpsTicks-1);if(lowFpsTicks>=5){if(settings.shaderProfile==='cinematic')settings.shaderProfile='reimagined';else{settings.shadersEnabled=false;settings.godrays=false;settings.bloom=false}settings.renderScale=Math.max(.55,settings.renderScale-.1);STORE.setItem('br4_settings',JSON.stringify(settings));applyCssSettings();resizeRenderer();lowFpsTicks=0;qualityCooldown=15;toast('Adaptive Quality → '+effectiveShaderProfile().toUpperCase(),2600)}}
