function loop(t){const dt=Math.min(.04,(t-game.last)/1000||.016);game.last=t;if(game.running&&!game.paused){updateTarget();updatePhysics(dt);updateMining(dt);updateMobs(dt);updateDrops(dt);updateFurnace(dt);updateDay(dt);streamChunks();processMeshQueue(1);game.saveClock+=dt;if(game.saveClock>18){game.saveClock=0;saveWorld(true)}}renderFrame();game.frame++;game.fpsTimer+=dt;if(game.fpsTimer>=1){game.fps=game.frame;game.frame=0;game.fpsTimer=0;updateDebug();adaptiveGraphics()}requestAnimationFrame(loop)}

// ---------- Start, quit and boot ----------
async function startWorld(id){const meta=worldMetaList().find(w=>w.id===id);if(!meta){toast('World not found');return}audio.resume();currentWorld=meta;worldSeed=hashString(meta.seed);game.mode=meta.mode;game.difficulty=meta.difficulty;closeScreen(dom.worlds);closeScreen(dom.main);openScreen(dom.loading);$('#loadingTitle').textContent='BUILDING '+meta.name.toUpperCase();$('#loadingDetail').textContent='Reading world save…';$('#loadingFill').style.width='4%';await sleep(35);
 for(const m of chunkMeshes.values()){destroyMesh(m.opaque);destroyMesh(m.water)}chunkMeshes.clear();chunks.clear();dirtyChunks.clear();terrainCache.clear();meshQueue.length=0;mobs.length=0;drops.length=0;desiredChunks.clear();lastChunkX=99999;loadWorldData(meta);if(collides(player.x,player.y,player.z))spawnPlayer();$('#loadingFill').style.width='14%';$('#loadingDetail').textContent='Generating biomes, caves and ore fields…';await sleep(25);
 const pcx=Math.floor(player.x/CH),pcz=Math.floor(player.z/CH),arr=[];for(let dz=-settings.viewDistance;dz<=settings.viewDistance;dz++)for(let dx=-settings.viewDistance;dx<=settings.viewDistance;dx++){if(dx*dx+dz*dz>(settings.viewDistance+.45)**2)continue;arr.push([pcx+dx,pcz+dz,dx*dx+dz*dz])}arr.sort((a,b)=>a[2]-b[2]);desiredChunks=new Set(arr.map(x=>ckey(x[0],x[1])));$('#loadingFill').style.width='32%';$('#loadingDetail').textContent='Meshing spawn chunk…';meshChunk(pcx,pcz);for(const[cx,cz]of arr)if(cx!==pcx||cz!==pcz)meshQueue.push(ckey(cx,cz));await new Promise(requestAnimationFrame);lastChunkX=pcx;lastChunkZ=pcz;$('#loadingFill').style.width='100%';$('#loadingDetail').textContent='Realm ready';renderInventoryAll();buildRecipeBook();updateVitals();await sleep(120);closeScreen(dom.loading);openScreen(dom.hud);game.running=true;game.paused=false;game.last=performance.now();game.saveClock=0;toast(meta.name+' loaded')}
function quitToMenu(){saveWorld(true);game.running=false;game.paused=false;closeScreen($('#pauseOverlay'));closeScreen($('#inventoryOverlay'));closeScreen(dom.hud);openScreen(dom.main);currentWorld=null;for(const m of chunkMeshes.values()){destroyMesh(m.opaque);destroyMesh(m.water)}chunkMeshes.clear();chunks.clear();terrainCache.clear();mobs.length=0;drops.length=0}$('#quitBtn').onclick=quitToMenu;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function splash(){const s=['Procedural. Portable. Yours.','No fixed six-slot palette!','WebGL 1 compatible!','Dig deeper. Build smarter.','One seed, endless terrain.','Survive the first night.'];$('#splashText').textContent=s[(Math.random()*s.length)|0]}
async function boot(){try{applyCssSettings();bootStep('Checking platform…','Android-safe startup diagnostics are active.',4);diag('BlockRealm Legacy '+APP_VERSION);diag('Safe mode: '+(safeMode?'YES':'NO'));diag('Origin: '+location.origin+' · '+location.protocol);diag('User agent: '+navigator.userAgent);diag('Touch points: '+navigator.maxTouchPoints);diag('Screen: '+screen.width+'×'+screen.height+' @ '+(devicePixelRatio||1));await sleep(40);initRenderer();atlasURL=atlas.canvas.toDataURL('image/png');bootStep('Preparing game systems…','Generating pixel atlas and inventory UI.',55);syncSettingsUI();renderHotbar();buildRecipeBook();updateVitals();await sleep(40);bootStep('Loading local saves…','World library and offline storage are ready.',76);renderWorldList();splash();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('SW',e));dom.canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();fatal('Graphics context was lost. Close other heavy apps and reload.',new Error('webglcontextlost'))});bootStep('Ready','Compatible renderer started successfully.',100);await sleep(160);closeScreen(dom.boot);openScreen(dom.main);requestAnimationFrame(loop)}catch(e){dom.bootRetry.classList.remove('hidden');fatal('BlockRealm could not start safely.',e)}}
window.addEventListener('pagehide',()=>saveWorld(true));document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.running){saveWorld(true);game.paused=true}});
let settingsFromPause=false;$('#pauseSettingsBtn').onclick=()=>{settingsFromPause=true;closeScreen($('#pauseOverlay'));showSettings()};const settingsClose=$('[data-close="settingsScreen"]');settingsClose.onclick=()=>{closeScreen(dom.settings);if(settingsFromPause&&game.running){openScreen($('#pauseOverlay'));settingsFromPause=false}};const oldApply=$('#applySettings').onclick;$('#applySettings').onclick=()=>{oldApply();if(settingsFromPause&&game.running){openScreen($('#pauseOverlay'));settingsFromPause=false}};
window.BlockRealmAndroidPause=()=>{if(game.running){saveWorld(true);if(!game.paused)togglePause(true)}return true};
window.BlockRealmAndroidBack=()=>{const inv=$('#inventoryOverlay'),pause=$('#pauseOverlay');if(!inv.classList.contains('hidden')){closeInventory();return true}if(!pause.classList.contains('hidden')){togglePause(false);return true}for(const panel of [dom.settings,dom.create,dom.worlds,$('#aboutScreen')]){if(panel&&!panel.classList.contains('hidden')){closeScreen(panel);openScreen(dom.main);return true}}if(game.running){togglePause(true);return true}return false};
window.BlockRealmDebug={version:APP_VERSION,setScene:o=>{if(o.day!=null)game.day=mod(+o.day,1);if(o.yaw!=null)player.yaw=+o.yaw;if(o.pitch!=null)player.pitch=clamp(+o.pitch,-1.52,1.52);if(o.profile){settings.shadersEnabled=o.profile!=='off';if(o.profile!=='off')settings.shaderProfile=o.profile;applyCssSettings()}return{day:game.day,yaw:player.yaw,pitch:player.pitch,sky:skyState()}},faceSun:()=>{const d=skyState().dir;player.yaw=Math.atan2(-d[0],-d[2]);player.pitch=Math.asin(clamp(d[1],-1,1));return{yaw:player.yaw,pitch:player.pitch,dir:d}},getState:()=>({running:game.running,paused:game.paused,world:currentWorld?.name||null,seed:currentWorld?.seed||null,player:{x:player.x,y:player.y,z:player.z,health:player.health,hunger:player.hunger},chunks:chunkMeshes.size,mobs:mobs.length,drops:drops.length,renderer:gl?gl.getParameter(gl.VERSION):null,glInfo,shaderProfile:effectiveShaderProfile(),safeMode}),selfTest:()=>{const results=[];const test=(name,fn)=>{try{results.push({name,pass:!!fn()})}catch(e){results.push({name,pass:false,error:String(e)})}};test('Block solidity defaults',()=>BLOCKS[B.STONE].solid&&BLOCKS[B.GLASS].solid&&!BLOCKS[B.WATER].solid);const oldSeed=worldSeed;worldSeed=12345;test('Deterministic terrain',()=>JSON.stringify(terrainInfo(91,-37))===JSON.stringify(terrainInfo(91,-37)));worldSeed=oldSeed;const old=craftSlots.map(cloneStack),oldMode=inventoryMode;craftSlots.fill(null);inventoryMode='hand';craftSlots[0]=stack(B.OAK_LOG,1);test('Hand recipe log to planks',()=>currentRecipe()?.out===B.OAK_PLANKS);for(let i=0;i<9;i++)craftSlots[i]=old[i];inventoryMode=oldMode;test('Nine-slot hotbar',()=>inventory.slice(0,9).length===9);test('View-relative forward movement',()=>{const y=player.yaw;player.yaw=Math.PI/2;const sy=Math.sin(player.yaw),cy=Math.cos(player.yaw),tx=-sy,tz=-cy;player.yaw=y;return tx<-.99&&Math.abs(tz)<.01});test('Shader controls available',()=>!!$('#shadersEnabledToggle')&&['reimagined','cinematic'].includes(settings.shaderProfile));test('WebGL compatibility path',()=>!!gl);return results}};
$$('[data-close="worldsScreen"]').forEach(b=>b.onclick=()=>{closeScreen(dom.worlds);openScreen(dom.main)});$$('[data-close="createScreen"]').forEach(b=>b.onclick=()=>{closeScreen(dom.create);openScreen(dom.main)});
